# Recursively inventory a shared Drive folder via gws; writes CSV of every file.
param([string]$RootId = '0B703I8aAuIntZ1NyTVFmb0Vzejg', [string]$Out = "$PSScriptRoot\tb_inventory.csv")
$rows = [System.Collections.Generic.List[object]]::new()
$queue = [System.Collections.Generic.Queue[object]]::new()
$queue.Enqueue(@{ id = $RootId; path = "TB's Training Info" })
while ($queue.Count -gt 0) {
  $f = $queue.Dequeue(); $token = $null
  do {
    $p = @{ q = "'$($f.id)' in parents and trashed=false"; pageSize = 1000; fields = 'nextPageToken,files(id,name,mimeType,size)'; supportsAllDrives = $true; includeItemsFromAllDrives = $true }
    if ($token) { $p.pageToken = $token }
    $json = (gws drive files list --params ($p | ConvertTo-Json -Compress) 2>$null | Where-Object { $_ -notmatch '^Using keyring' }) -join "`n"
    $r = $json | ConvertFrom-Json
    foreach ($x in $r.files) {
      if ($x.mimeType -eq 'application/vnd.google-apps.folder') { $queue.Enqueue(@{ id = $x.id; path = "$($f.path)/$($x.name)" }) }
      else { $rows.Add([pscustomobject]@{ folder = $f.path; name = $x.name; mime = $x.mimeType; size = [int64]($x.size ?? 0); id = $x.id }) }
    }
    $token = $r.nextPageToken
  } while ($token)
}
$rows | Export-Csv $Out -NoTypeInformation -Encoding utf8
"files: $($rows.Count)  GB: $([math]::Round(($rows | Measure-Object size -Sum).Sum/1GB,2))"

