input.content:
# Flint step 0: catalog every knowledge file under the configured Drive roots.
# Metadata only, via the Drive API (gws) - no file content is read or downloaded,
# and no model tokens are spent. Duplicates are found by Drive's md5Checksum.
#
#   pwsh flint/scripts/build_manifest.ps1            # full run
#   pwsh flint/scripts/build_manifest.ps1 -Only "TB Training Info"
#
# Output: flint/data/manifest.csv (gitignored; file names can be sensitive)
#         flint/data/manifest_summary.md (committed; aggregate counts only)
param([string]$Only)
$ErrorActionPreference = 'Stop'
$here   = Split-Path $PSScriptRoot -Parent
$cfg    = Get-Content "$here/config/roots.json" -Raw | ConvertFrom-Json
$outDir = "$here/data"; New-Item -ItemType Directory -Force $outDir | Out-Null

$FOLDER = 'application/vnd.google-apps.folder'
$kinds = [ordered]@{
  paper_or_book = 'pdf|epub|mobi|djvu'
  document      = 'docx?|rtf|txt|md|odt|pages|gdoc|document'
  slides        = 'pptx?|key|odp|presentation'
  video         = 'mp4|mov|m4v|mkv|wmv|avi|webm|mpg|mpeg|flv|3gp|video'
  audio         = 'mp3|m4a|wav|aac|ogg|flac|wma|audio'
  data          = 'xlsx?|xlsm|csv|tsv|json|parquet|db|sqlite|spreadsheet'
  image         = 'jpe?g|png|gif|heic|tiff?|bmp|webp|image'
  archive       = 'zip|rar|7z|tar|gz'
}
function Get-Kind($name, $mime) {
  $ext = if ($name -match '\.([A-Za-z0-9]{1,5})$') { $Matches[1].ToLower() } else { '' }
  $probe = "$ext $($mime -replace '.*[/.]','')"
  foreach ($k in $kinds.Keys) { if ($probe -match "(?i)(^|\s)($($kinds[$k]))(\s|$)") { return @($k, $ext) } }
  if ($mime -match 'video/') { return @('video', $ext) }
  if ($mime -match 'audio/') { return @('audio', $ext) }
  if ($mime -match 'image/') { return @('image', $ext) }
  return @('other', $ext)
}

function Invoke-List($q, $token) {
  $p = @{ q = $q; pageSize = 1000; supportsAllDrives = $true; includeItemsFromAllDrives = $true
          fields = 'nextPageToken,files(id,name,mimeType,size,md5Checksum,modifiedTime,shortcutDetails)' }
  if ($token) { $p.pageToken = $token }
  $args = $p | ConvertTo-Json -Compress
  for ($try = 1; $try -le 4; $try++) {
    $raw = (gws drive files list --params $args 2>$null | Where-Object { $_ -notmatch '^Using keyring' }) -join "`n"
    try { $r = $raw | ConvertFrom-Json; if ($null -ne $r.files -or $r.PSObject.Properties.Name -contains 'files') { return $r } } catch {}
    Start-Sleep -Seconds (3 * $try)
  }
  throw "gws list failed after retries: $q"
}

# Resolve shared folders by name pattern.
$roots = [System.Collections.Generic.List[object]]::new()
$cfg.roots | ForEach-Object { $roots.Add($_) }
$shared = (Invoke-List "sharedWithMe = true and mimeType = '$FOLDER'" $null).files
foreach ($s in $shared) {
  if ($cfg.shared_folder_patterns | Where-Object { $s.name -match $_ }) {
    $roots.Add([pscustomobject]@{ label = "shared/$($s.name)"; id = $s.id; priority = $cfg.shared_priority })
  }
}
if ($Only) { $roots = @($roots | Where-Object { $_.label -eq $Only }) }

$rows = [System.Collections.Generic.List[object]]::new()
$skipped = @{}
foreach ($root in $roots) {
  Write-Host "Listing $($root.label) ..."
  $seen  = @{}
  $queue = [System.Collections.Generic.Queue[object]]::new()
  $queue.Enqueue(@{ id = $root.id; path = '' })
  while ($queue.Count) {
    $f = $queue.Dequeue()
    if ($seen[$f.id]) { continue }; $seen[$f.id] = $true
    $token = $null
    do {
      $r = Invoke-List "'$($f.id)' in parents and trashed=false" $token
      foreach ($x in $r.files) {
        $path = if ($f.path) { "$($f.path)/$($x.name)" } else { $x.name }
        if ("$($root.label)/$path" -match $cfg.exclude_path_regex) { $skipped['excluded path']++; continue }
        $isShortcutFolder = $x.shortcutDetails -and $x.shortcutDetails.targetMimeType -eq $FOLDER
        if ($x.mimeType -eq $FOLDER -or $isShortcutFolder) {
          $id = if ($isShortcutFolder) { $x.shortcutDetails.targetId } else { $x.id }
          $queue.Enqueue(@{ id = $id; path = $path }); continue
        }
        $kind, $ext = Get-Kind $x.name $x.mimeType
        if ($kind -eq 'data'  -and -not $root.keep_data_files) { $skipped['data file (privacy)']++; continue }
        if ($kind -eq 'image' -and -not $root.keep_images)     { $skipped['image']++; continue }
        if ($kind -eq 'other') { $skipped['other type']++; continue }
        $rows.Add([pscustomobject]@{
          source = $root.label; priority = [int]$root.priority
          subfolder = ($path -split '/')[0]; path = $path; name = $x.name; ext = $ext; kind = $kind
          size = [int64]($x.size ?? 0); md5 = $x.md5Checksum; modified = $x.modifiedTime; id = $x.id
          dup_key = ''; canonical = $true; dup_count = 1
        })
      }
      $token = $r.nextPageToken
    } while ($token)
  }
}

# Dedup: md5 when Drive has one (binary files), else name+size (Google-native files).
foreach ($g in ($rows | Group-Object { if ($_.md5) { "md5:$($_.md5)" } else { "ns:$($_.name.ToLower())|$($_.size)" } })) {
  $ordered = $g.Group | Sort-Object priority, path
  $i = 0
  foreach ($row in $ordered) { $row.dup_key = $g.Name; $row.dup_count = $g.Count; $row.canonical = ($i -eq 0); $i++ }
}

$rows | Sort-Object source, path | Export-Csv "$outDir/manifest.csv" -NoTypeInformation -Encoding utf8

# Summary: aggregate counts only, safe to commit.
$canon = $rows | Where-Object canonical
$gb = { param($s) '{0:N1}' -f (($s | Measure-Object size -Sum).Sum / 1GB) }
$md = [System.Collections.Generic.List[string]]::new()
$md.Add("# Flint manifest summary"); $md.Add('')
$md.Add("Generated $(Get-Date -Format 'yyyy-MM-dd HH:mm') by ``flint/scripts/build_manifest.ps1``. Metadata only.")
$md.Add(''); $md.Add("- Files catalogued: $($rows.Count) ($(& $gb $rows) GB)")
$md.Add("- Unique after dedup: $($canon.Count) ($(& $gb $canon) GB)")
$md.Add("- Duplicate copies: $($rows.Count - $canon.Count)")
$md.Add("- Skipped: " + (($skipped.GetEnumerator() | Sort-Object Name | ForEach-Object { "$($_.Name) $($_.Value)" }) -join ', '))
$md.Add(''); $md.Add('## Unique files by kind'); $md.Add(''); $md.Add('| Kind | Files | GB |'); $md.Add('|---|---:|---:|')
$canon | Group-Object kind | Sort-Object Count -Descending | ForEach-Object { $md.Add("| $($_.Name) | $($_.Count) | $(& $gb $_.Group) |") }
$md.Add(''); $md.Add('## Unique files by source'); $md.Add(''); $md.Add('| Source | Files | Papers/books | Video | Audio | GB |'); $md.Add('|---|---:|---:|---:|---:|---:|')
$canon | Group-Object source | Sort-Object Count -Descending | ForEach-Object {
  $k = $_.Group | Group-Object kind -AsHashTable
  $md.Add("| $($_.Name) | $($_.Count) | $(@($k['paper_or_book']).Count) | $(@($k['video']).Count) | $(@($k['audio']).Count) | $(& $gb $_.Group) |")
}
$md | Set-Content "$outDir/manifest_summary.md" -Encoding utf8
"rows=$($rows.Count) unique=$($canon.Count)"

