# Copy a shared Drive folder into Eric's own Drive, server-side, so Flint ingests a
# fixed copy he controls instead of a folder its owner is still editing.
#
#   pwsh scripts/snapshot_shared_folder.ps1                       # TB's Training Info defaults
#   pwsh scripts/snapshot_shared_folder.ps1 -DryRun               # list what would be copied
#
# Nothing is downloaded: every file is copied with the Drive API (files.copy). The log
# (data/snapshot_<name>.csv, gitignored) maps each source id to its copy, so a re-run
# resumes and skips anything already copied. Shortcuts are logged and skipped.
param(
  [string]$SourceId     = '0B703I8aAuIntZ1NyTVFmb0Vzejg',          # TB's Training Info (Thomas Barbeau)
  [string]$DestParentId = '1j67T3pV6wXthLY4dbVsXThqNMYTKwyAO',     # 00_Primary_Storage_Drive/09_PRO_DEV
  [string]$Name         = "TB's Training Info (snapshot 2026-09-26)",
  [switch]$DryRun
)
$ErrorActionPreference = 'Stop'
$FOLDER  = 'application/vnd.google-apps.folder'
$dataDir = Join-Path (Split-Path $PSScriptRoot -Parent) 'data'
New-Item -ItemType Directory -Force $dataDir | Out-Null
$logPath = Join-Path $dataDir ("snapshot_{0}.csv" -f ($Name -replace '[^A-Za-z0-9]+','_').Trim('_'))

function Invoke-Gws([string[]]$gwsArgs) {
  for ($try = 1; $try -le 4; $try++) {
    $raw = (& gws @gwsArgs 2>&1 | Where-Object { "$_" -notmatch '^Using keyring' }) -join "`n"
    try { $r = $raw | ConvertFrom-Json; if (-not $r.error) { return $r } } catch {}
    if ($try -eq 4) { throw "gws failed: $($gwsArgs -join ' ') :: $raw" }
    Start-Sleep -Seconds (4 * $try)
  }
}
function Get-Children($id) {
  $out = @(); $token = $null
  do {
    $p = @{ q = "'$id' in parents and trashed=false"; pageSize = 1000; supportsAllDrives = $true; includeItemsFromAllDrives = $true
            fields = 'nextPageToken,files(id,name,mimeType,size)' }
    if ($token) { $p.pageToken = $token }
    $r = Invoke-Gws @('drive','files','list','--params',($p | ConvertTo-Json -Compress))
    $out += $r.files; $token = $r.nextPageToken
  } while ($token)
  return $out
}

# Resume state: source id -> new id.
$done = @{}
if (Test-Path $logPath) { Import-Csv $logPath | Where-Object { $_.status -eq 'ok' } | ForEach-Object { $done[$_.src_id] = $_.new_id } }
function Write-Log($kind, $src, $new, $path, $status) {
  [pscustomobject]@{ kind = $kind; src_id = $src; new_id = $new; path = $path; status = $status; at = (Get-Date -Format s) } |
    Export-Csv $logPath -Append -NoTypeInformation -Encoding utf8
}
function New-Folder($name, $parent, $srcId, $path) {
  if ($done[$srcId]) { return $done[$srcId] }
  if ($DryRun) { return "dry-$srcId" }
  $body = @{ name = $name; mimeType = $FOLDER; parents = @($parent) } | ConvertTo-Json -Compress
  $r = Invoke-Gws @('drive','files','create','--json',$body,'--params','{"fields":"id","supportsAllDrives":true}')
  Write-Log 'folder' $srcId $r.id $path 'ok'; $done[$srcId] = $r.id
  return $r.id
}

$rootId = New-Folder $Name $DestParentId $SourceId ''
$queue = [System.Collections.Generic.Queue[object]]::new()
$queue.Enqueue(@{ src = $SourceId; dest = $rootId; path = '' })
$n = @{ copied = 0; skipped_done = 0; shortcut = 0; failed = 0; folders = 0 }
