import sys
from pypdf import PdfReader

r = PdfReader(sys.argv[1])

def walk(items, depth=0):
    for it in items:
        if isinstance(it, list):
            if depth < 1:
                walk(it, depth + 1)
            continue
        try:
            page = r.get_destination_page_number(it) + 1
        except Exception:
            page = "?"
        print(f"{'  ' * depth}{page:>4}  {it.title[:90]}")

walk(r.outline)

